import { Arrow, BLUE, Box, Label, Line, WHITE } from '../../../diagrams/primitives'

/**
 * R1, SFT (LoRA): Nemotron 3.5 Super VL answers a synthetic denial (a training
 * room), and the gap between its attempt and the ideal response is the loss.
 * The ideal response is generated by Nemotron 3.5 Super VL itself, with GLM 5.3
 * as judge and teacher: passing attempts are kept, and failed ones are
 * corrected by GLM 5.3. Canvas: 960 x 310 px (set in `index.ts`). White, with
 * the accent (blue) on the models.
 */
export function R1Sft() {
  return (
    <g color={WHITE}>
      {/* synthetic denial → Nemotron */}
      <Label x={75} y={36} anchor="middle">synthetic denial</Label>
      <Label x={75} y={52} anchor="middle">(training room)</Label>
      <Box x={14} y={59.5} w={122} h={61} />
      <Line from={[29, 80]} to={[120.5, 80]} opacity={0.3} />
      <Line from={[29, 97]} to={[95, 97]} opacity={0.3} />
      <Arrow points={[[140, 90], [200.5, 90]]} />

      <Box color={BLUE} x={204} y={45} w={142} h={90} radius={13.5} strokeWidth={3.4} />
      <Label color={BLUE} x={275} y={85} size={17.8} anchor="middle">Nemotron 3.5</Label>
      <Label color={BLUE} x={275} y={107} size={17.8} anchor="middle">Super VL</Label>

      {/* Nemotron → its attempt */}
      <Arrow points={[[349.5, 90], [444.5, 90]]} />
      <Label x={529} y={50} anchor="middle">model's attempt</Label>
      <Box x={448} y={59.5} w={162.5} h={61} dashed />
      <Line from={[463, 80]} to={[595.5, 80]} opacity={0.3} />
      <Line from={[463, 97]} to={[560, 97]} opacity={0.3} />

      {/* attempt vs. ideal response = loss */}
      <Arrow points={[[529, 127], [529, 193]]} both strokeWidth={2.5} headLength={12} headWidth={13.5} />
      <Label x={546} y={165} size={14.4}>gap = loss</Label>

      <Box x={448} y={200} w={162.5} h={61} filled />
      <Line from={[463, 220.5]} to={[595.5, 220.5]} opacity={0.35} />
      <Line from={[463, 237.5]} to={[573.5, 237.5]} opacity={0.35} />
      <Label x={463} y={281}>ideal response</Label>

      {/* how the ideal response is generated: Nemotron writes, GLM 5.3 judges and corrects */}
      <Arrow points={[[676, 230.5], [614, 230.5]]} />
      <Box color={BLUE} x={680} y={200} w={108} h={61} radius={10} />
      <Label color={BLUE} x={734} y={226} size={15} anchor="middle">GLM 5.3</Label>
      <Label color={BLUE} x={734} y={245} size={14} anchor="middle">judge + teacher</Label>
      <Label x={734} y={281} italic opacity={0.7} anchor="middle">keeps passing attempts,</Label>
      <Label x={734} y={298} italic opacity={0.7} anchor="middle">corrects failed ones</Label>

      <Arrow points={[[832, 230.5], [792, 230.5]]} />
      <Box color={BLUE} x={836} y={200} w={104} h={61} radius={10} />
      <Label color={BLUE} x={888} y={226} size={14.5} anchor="middle">Nemotron 3.5</Label>
      <Label color={BLUE} x={888} y={245} size={14.5} anchor="middle">Super VL</Label>

      {/* the loss flows back to Nemotron */}
      <Arrow points={[[444.5, 230.5], [275, 230.5], [275, 138.5]]} headLength={13.5} headWidth={13.5} />
      <Label x={312} y={220} italic>update LoRA weights</Label>
      <Label x={307} y={256} italic opacity={0.7}>to shrink the gap</Label>
    </g>
  )
}
